    L.routes.forEach(function(r){ g+='<polyline class="dt-route" points="'+pl(r.pts)+'" fill="none" stroke="'+side+'" stroke-width="1.5" stroke-dasharray="5 3" opacity="0.9"><title>'+esc("Ordered route: "+r.col)+'</title></polyline>'; });
