  for(i=0;i<n;i++) for(j=0;j<n-i;j++){ var p0=row[i]+j, p1=row[i+1]+j, p2=row[i]+j+1;
    idx.push(p0,p1,p2); if(j<n-i-1) idx.push(p1,row[i+1]+j+1,p2); }
