    dense:a.leg?2:0,   /* Stage 4D: a derived arrow kept to its path (its drawn-on part follows the formation) */
    cap:true, fillOp:ARROW_CAP.OP, edgeOp:ARROW_EDGE_OP, border:true, ground:true, role:"arrow",   /* Stage 8, 8B (decision 241) */
