  var c=cv.getContext("2d");
  c.strokeStyle=TOKENS.sym.label[mode==="staff"?"paper":"dark"].annotation; c.lineWidth=7;
  c.beginPath(); c.arc(64,64,40,0,Math.PI*2); c.stroke();
