  if(mode==="staff"){ MAPCAM.glideTo(toTgt.x,toTgt.z,mapWppAt(toPos.distanceTo(toTgt)),ms); return; }
  if(RM) mlReset("at once");   /* Stage 8, 8C: under reduced motion the glide is a jump (MLS) */
