  var wrap=el("div","dossier");
  if(!tl) return wrap;
  var kind={ridge:"Ridge line",scarp:"Escarpment",valley:"Valley floor",
            defile:"Defile",dead:"Dead ground"}[tl.t];
  var col=TOKENS.sym.analysis[tl.t].line;
